INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000810140','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000810140","revision":1,"targetId":"80000000-0000-4000-8000-000000008114","prompt":"Weil sie nach der Geburt weniger arbeitete, beantragte sie ___ als Einkommensersatz.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"This benefit partly replaces earnings lost during early parenthood.","de":"Diese Leistung ersetzt einen Teil des entfallenden Einkommens nach der Geburt."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Kindergeld"},{"id":"1","text":"Wohngeld"},{"id":"2","text":"Elterngeld"},{"id":"3","text":"Arbeitslosengeld"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Elterngeld means parental income-replacement benefit. This benefit partly replaces earnings lost during early parenthood.","de":"Elterngeld bedeutet staatliche Leistung zum teilweisen Ersatz von Einkommen nach Geburt. Diese Leistung ersetzt einen Teil des entfallenden Einkommens nach der Geburt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Weil sie nach der Geburt weniger arbeitete, beantragte sie Elterngeld als Einkommensersatz.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L639 (caf2f99beeed6687b74dc98097d80c97b215768ae460695be41d647671b46e2b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; on