INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000810141','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000810141","revision":1,"targetId":"80000000-0000-4000-8000-000000008114","prompt":"Die Leistung ersetzt einen Teil des wegfallenden Einkommens nach der Geburt. Sie heißt ___.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"It compensates for reduced work income after a child''s birth.","de":"Die Leistung gleicht geringere Erwerbseinnahmen nach der Geburt teilweise aus."},"options":[{"id":"0","text":"Kindergeld"},{"id":"1","text":"Wohngeld"},{"id":"2","text":"Bürgergeld"},{"id":"3","text":"Elterngeld"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Elterngeld means parental income-replacement benefit. It compensates for reduced work income after a child''s birth.","de":"Elterngeld bedeutet staatliche Leistung zum teilweisen Ersatz von Einkommen nach Geburt. Die Leistung gleicht geringere Erwerbseinnahmen nach der Geburt teilweise aus."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Leistung ersetzt einen Teil des wegfallenden Einkommens nach der Geburt. Sie heißt Elterngeld.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L639 (caf2f99beeed6687b74dc98097d80c97b215768ae460695be41d647671b46e2b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.',