INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000810181','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000810181","revision":1,"targetId":"80000000-0000-4000-8000-000000008118","prompt":"Der Motor benötigt ___, um die Maschine anzutreiben.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"A motor needs power to do work.","de":"Ein Motor braucht eine Energiequelle zum Arbeiten."},"options":[{"id":"0","text":"Geduld"},{"id":"1","text":"Hoffnung"},{"id":"2","text":"Erlaubnis"},{"id":"3","text":"Energie"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Energie means energy needed for work or activity. A motor needs power to do work.","de":"Energie bedeutet Fähigkeit, Arbeit zu verrichten oder etwas anzutreiben. Ein Motor braucht eine Energiequelle zum Arbeiten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Motor benötigt Energie, um die Maschine anzutreiben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L645 (aa25c2a4295ac62828e10e57cdf504f438894c7f42da84c4ed14751af863155b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
