INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000810190','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000810190","revision":1,"targetId":"80000000-0000-4000-8000-000000008119","prompt":"Die bessere Dämmung führte zu einer deutlichen ___ beim Heizen.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Insulation reduces heating demand.","de":"Dämmung senkt den Energiebedarf beim Heizen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Energieverschwendung"},{"id":"1","text":"Energieeinsparung"},{"id":"2","text":"Energieerhöhung"},{"id":"3","text":"Energieversorgung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Energieeinsparung means reduction in energy consumption. Insulation reduces heating demand.","de":"Energieeinsparung bedeutet Verringerung des Energieverbrauchs. Dämmung senkt den Energiebedarf beim Heizen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die bessere Dämmung führte zu einer deutlichen Energieeinsparung beim Heizen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L646 (3a2faf11bcd44940dbaf87d12b806c9ae7b7927f42f6d28b3adc7657c2cce89b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
