INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000830060','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000830060","revision":1,"targetId":"80000000-0000-4000-8000-000000008306","prompt":"Bei krankheitsbedingter Arbeitsunfähigkeit kann Anspruch auf ___ bestehen.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Pay may continue during an eligible sick leave.","de":"Bei berechtigter Krankheit kann das Entgelt weitergezahlt werden."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Kündigung"},{"id":"1","text":"Entgeltfortzahlung"},{"id":"2","text":"Abmahnung"},{"id":"3","text":"Arbeitslosigkeit"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Entgeltfortzahlung means continued wage payment during certain absences. Pay may continue during an eligible sick leave.","de":"Entgeltfortzahlung bedeutet Weiterzahlung des Arbeitsentgelts bei bestimmter Abwesenheit. Bei berechtigter Krankheit kann das Entgelt weitergezahlt werden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Bei krankheitsbedingter Arbeitsunfähigkeit kann Anspruch auf Entgeltfortzahlung bestehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L653 (ea68bec3e34a3121f59b525e2ad83f9e74dcecd401d8d54fa52706136530bb21), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or non